-- =========================================================
--  Conociendo Formosa · Base de datos
--  Desarrollado por Dalila Spindola Dev
--  Importar en phpMyAdmin o: mysql -u root -p < formosa.sql
-- =========================================================
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
CREATE DATABASE IF NOT EXISTS formosa_turismo CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE formosa_turismo;

DROP TABLE IF EXISTS bibliografia, puntajes, resenas, preguntas, imagenes, lugares, departamentos, pueblos, slides, config, usuarios;

CREATE TABLE usuarios (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nombre VARCHAR(100) NOT NULL,
  usuario VARCHAR(50) NOT NULL UNIQUE,
  password VARCHAR(255) NOT NULL,
  ultimo_acceso DATETIME NULL,
  creado DATETIME DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

CREATE TABLE config (
  clave VARCHAR(60) PRIMARY KEY,
  valor TEXT,
  etiqueta VARCHAR(150),
  tipo ENUM('text','textarea','image','bool') DEFAULT 'text',
  grupo VARCHAR(40) DEFAULT 'general'
) ENGINE=InnoDB;

CREATE TABLE departamentos (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nombre VARCHAR(100) NOT NULL,
  slug VARCHAR(120) NOT NULL UNIQUE,
  cabecera VARCHAR(120),
  descripcion TEXT,
  color VARCHAR(7) DEFAULT '#2E9E6A',
  imagen VARCHAR(500),
  orden INT DEFAULT 0
) ENGINE=InnoDB;

CREATE TABLE lugares (
  id INT AUTO_INCREMENT PRIMARY KEY,
  departamento_id INT NOT NULL,
  nombre VARCHAR(150) NOT NULL,
  slug VARCHAR(170) NOT NULL UNIQUE,
  categoria ENUM('cultura','naturaleza','paseo') NOT NULL DEFAULT 'cultura',
  resumen VARCHAR(255),
  descripcion TEXT,
  dato_curioso TEXT,
  importancia TEXT,
  habitantes TEXT,
  como_llegar TEXT,
  fuentes TEXT,
  lat DECIMAL(10,7) NOT NULL,
  lng DECIMAL(10,7) NOT NULL,
  map_x DECIMAL(6,3) NULL,
  map_y DECIMAL(6,3) NULL,
  destacado TINYINT(1) DEFAULT 0,
  activo TINYINT(1) DEFAULT 1,
  visitas INT DEFAULT 0,
  creado DATETIME DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_lugar_depto FOREIGN KEY (departamento_id) REFERENCES departamentos(id) ON DELETE RESTRICT,
  INDEX (categoria), INDEX (activo)
) ENGINE=InnoDB;

CREATE TABLE imagenes (
  id INT AUTO_INCREMENT PRIMARY KEY,
  lugar_id INT NOT NULL,
  url VARCHAR(500) NOT NULL,
  titulo VARCHAR(200),
  credito VARCHAR(150),
  principal TINYINT(1) DEFAULT 0,
  orden INT DEFAULT 0,
  CONSTRAINT fk_img_lugar FOREIGN KEY (lugar_id) REFERENCES lugares(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE preguntas (
  id INT AUTO_INCREMENT PRIMARY KEY,
  lugar_id INT NOT NULL,
  pregunta VARCHAR(255) NOT NULL,
  opcion_a VARCHAR(150) NOT NULL,
  opcion_b VARCHAR(150) NOT NULL,
  opcion_c VARCHAR(150) NOT NULL,
  opcion_d VARCHAR(150) NOT NULL,
  correcta CHAR(1) NOT NULL,
  explicacion VARCHAR(255),
  CONSTRAINT fk_preg_lugar FOREIGN KEY (lugar_id) REFERENCES lugares(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE pueblos (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nombre VARCHAR(80) NOT NULL,
  nombre_impuesto VARCHAR(80),
  descripcion TEXT,
  color VARCHAR(7) DEFAULT '#C2552F',
  icono VARCHAR(60) DEFAULT 'fa-people-group',
  imagen VARCHAR(500),
  orden INT DEFAULT 0
) ENGINE=InnoDB;

CREATE TABLE slides (
  id INT AUTO_INCREMENT PRIMARY KEY,
  titulo VARCHAR(150),
  subtitulo VARCHAR(255),
  imagen VARCHAR(500) NOT NULL,
  boton_texto VARCHAR(60),
  boton_link VARCHAR(255),
  orden INT DEFAULT 0,
  activo TINYINT(1) DEFAULT 1
) ENGINE=InnoDB;

CREATE TABLE resenas (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nombre VARCHAR(80) NOT NULL,
  ciudad VARCHAR(80),
  calificacion TINYINT NOT NULL,
  comentario TEXT NOT NULL,
  lugar_id INT NULL,
  estado ENUM('pendiente','aprobada','oculta') DEFAULT 'aprobada',
  ip VARCHAR(45),
  creado DATETIME DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_res_lugar FOREIGN KEY (lugar_id) REFERENCES lugares(id) ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE puntajes (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nombre VARCHAR(40) NOT NULL,
  juego VARCHAR(30) NOT NULL DEFAULT 'trivia',
  puntos INT NOT NULL,
  aciertos INT DEFAULT 0,
  total INT DEFAULT 0,
  creado DATETIME DEFAULT CURRENT_TIMESTAMP,
  INDEX (juego, puntos)
) ENGINE=InnoDB;

CREATE TABLE bibliografia (
  id INT AUTO_INCREMENT PRIMARY KEY,
  categoria ENUM('programa','oficial','academica','audiovisual','periodistica') NOT NULL DEFAULT 'oficial',
  cita TEXT NOT NULL,
  url VARCHAR(500),
  orden INT DEFAULT 0
) ENGINE=InnoDB;

SET FOREIGN_KEY_CHECKS = 1;

