INSERT INTO config (clave, valor, etiqueta, tipo, grupo) VALUES
('sitio_nombre', 'Conociendo Formosa', 'Nombre del sitio', 'text', 'general'),
('sitio_lema', 'Paraíso subtropical del norte argentino', 'Lema', 'text', 'general'),
('hero_titulo', 'Conociendo Formosa', 'Título principal', 'text', 'inicio'),
('hero_texto', 'Te invitamos a recorrer Formosa y descubrir su historia, cultura, naturaleza y las personas que forman parte de ella.', 'Texto principal', 'textarea', 'inicio'),
('sobre_historia', 'Fundada el 8 de abril de 1879 por el comandante Luis Jorge Fontana, Formosa fue territorio nacional hasta 1955, cuando se convirtió en provincia. Su historia mezcla fortines, ferrocarril, colonos e inmigrantes con la presencia milenaria de sus pueblos.', 'Historia', 'textarea', 'sobre'),
('sobre_cultura', 'Chamamé, polca y guaraní en el este; tradiciones criollas y wichí en el oeste. Fiestas como la Nacional del Río o la del Pomelo muestran una cultura alegre, hospitalaria y diversa.', 'Cultura', 'textarea', 'sobre'),
('sobre_naturaleza', 'El Bañado La Estrella, el Parque Nacional Río Pilcomayo y la Reserva Laguna Oca son hogar de jabirúes, yacarés, carpinchos, osos hormigueros y cientos de especies de aves.', 'Naturaleza', 'textarea', 'sobre'),
('sobre_imagen', 'https://commons.wikimedia.org/wiki/Special:FilePath/Coronel_Lu%C3%ADs_Jorge_Fontana_%281879%29.JPG?width=800', 'Imagen sección Historia', 'image', 'sobre'),
('contacto_email', 'contacto@conociendoformosa.com.ar', 'Email de contacto', 'text', 'contacto'),
('contacto_telefono', '+54 370 400-0000', 'Teléfono', 'text', 'contacto'),
('contacto_direccion', 'Formosa, Argentina', 'Dirección', 'text', 'contacto'),
('red_facebook', '#', 'Facebook (URL)', 'text', 'redes'),
('red_instagram', '#', 'Instagram (URL)', 'text', 'redes'),
('red_youtube', '#', 'YouTube (URL)', 'text', 'redes'),
('resenas_moderar', '0', 'Moderar reseñas antes de publicarlas (1 = sí, 0 = no)', 'bool', 'resenas'),
('footer_texto', 'Un proyecto para conocer, valorar y compartir los lugares turísticos, emblemáticos y originarios de Formosa.', 'Texto del pie de página', 'textarea', 'general'),
('sobre_titulo', 'Una provincia diversa', 'Título ''Sobre Formosa''', 'text', 'sobre'),
('sobre_intro', 'Entre el río Paraguay y el Pilcomayo, Formosa reúne humedales, monte chaqueño, ciudades de frontera y cuatro pueblos originarios: qom, wichí, pilagá y nivaclé. Según el Censo 2022, el 7,8% de su población se reconoce indígena o descendiente de pueblos indígenas, una de las proporciones más altas del país.', 'Introducción', 'textarea', 'sobre'),
('proyecto_titulo', 'Sobre este proyecto', 'Título de la sección del proyecto', 'text', 'proyecto'),
('proyecto_eje', 'Eje 2 · La diversidad sociocultural de Formosa: las miradas sobre el otro, políticas de Estado y relaciones interétnicas', 'Eje temático', 'text', 'proyecto'),
('proyecto_texto', 'Soy Dalila Spindola, estudiante de 3.er año de la Tecnicatura Superior en Desarrollo de Software del I.S.F.D. y T. «República Federal de Alemania». Este mapa es mi trabajo final del seminario Análisis de la Realidad Sociocultural de Formosa y se enmarca en el Eje 2: «La diversidad sociocultural de Formosa: las miradas sobre el otro, políticas de Estado y relaciones interétnicas».
INSERT INTO departamentos (id, nombre, slug, cabecera, descripcion, color, imagen, orden) VALUES
(1, 'Formosa', 'formosa', 'Formosa', 'La capital, sobre la «Vuelta Fermosa» del río Paraguay. Allí conviven la historia oficial de la fundación, una reserva de biosfera y comunidades qom urbanas.', '#7BCCAE', 'https://commons.wikimedia.org/wiki/Special:FilePath/Vista_Costanera_-_panoramio.jpg?width=1400', 1),
(2, 'Pilcomayo', 'pilcomayo', 'Clorinda', 'Frontera con Paraguay, humedales del Parque Nacional Río Pilcomayo y la lucha territorial de la comunidad qom La Primavera.', '#FADF66', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pnpilcomayofsa2.jpg?width=1400', 2),
(3, 'Pilagás', 'pilagas', 'El Espinillo', 'Riachos, esteros y pueblos rurales, con la antigua misión franciscana de Tacaaglé y una fuerte presencia qom.', '#FAB05A', 'https://commons.wikimedia.org/wiki/Special:FilePath/RIACHO_PORTE%C3%91O.jpg?width=1400', 3),
(4, 'Laishí', 'laishi', 'San Francisco de Laishí', 'Lagunas de pesca sobre el río Paraguay y la historia de la misión franciscana de Laishí, contada también desde la voz indígena.', '#FC9FA8', NULL, 4),
(5, 'Pirané', 'pirane', 'Pirané', 'Corazón productivo del centro-este: colonias agrícolas, montes de palo santo y la ribera del Bermejo.', '#6ABFF7', NULL, 5),
(6, 'Patiño', 'patino', 'Comandante Fontana', 'Puerta al Bañado La Estrella y territorio de la memoria del pueblo pilagá.', '#BE96ED', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ba%C3%B1adolaestrellafsa.jpg?width=1400', 6),
(7, 'Bermejo', 'bermejo', 'Laguna Yema', 'Oeste semiárido: monte chaqueño, río Teuco y comunidades wichí.', '#B0E27F', NULL, 7),
(8, 'Matacos', 'matacos', 'Ingeniero Guillermo N. Juárez', 'Un nombre que recuerda cómo se llamó desde afuera al pueblo wichí; tierra del chaguar y del quebracho.', '#FD9FAA', NULL, 8),
(9, 'Ramón Lista', 'ramon-lista', 'General Enrique Mosconi', 'El extremo oeste de Formosa, a orillas del Pilcomayo, con una población mayoritariamente wichí.', '#FED96F', NULL, 9);
INSERT INTO lugares (id, departamento_id, nombre, slug, categoria, resumen, descripcion, dato_curioso, importancia, habitantes, como_llegar, fuentes, lat, lng, map_x, map_y, destacado, activo) VALUES
(1, 1, 'Ciudad de Formosa y Costanera Vuelta Fermoza', 'ciudad-de-formosa-y-costanera-vuelta-fermoza', 'paseo', 'La capital provincial, fundada en 1879 a orillas del río Paraguay, con 7 km de costanera.', 'La ciudad de Formosa fue fundada el 8 de abril de 1879 por el mayor Luis Jorge Fontana, por sugerencia del gobernador Lucio V. Mansilla, en el marco del avance del Estado nacional sobre el Chaco. Su nombre viene de «Punta Hermosa» o «Formosa», como llamaban los españoles a ese lugar por la belleza del río Paraguay. En 1884 Formosa se separó del territorio del Chaco y la ciudad fue punto de partida para la colonización de la región. Hoy su gran espacio público es la Costanera «Vuelta Fermoza», de unos 7 km, con ciclovía frente al río, donde la gente se reúne a compartir mate o tereré.', 'Para los españoles era la «Punta Hermosa»: de ahí viene el nombre Formosa.', 'Frente a la ciudad, el río Paraguay forma amplias curvas y lagunas que albergan muchas especies vegetales y animales, varias con criterios de conservación; hacia el sur se extiende la Reserva de Biosfera Laguna Oca. La ciudad también es puerta de entrada a la provincia: se llega por la RN 11 desde Clorinda, por la RN 81 desde el oeste, por avión al aeropuerto El Pucú o cruzando el río desde Alberdi (Paraguay).', 'Es una ciudad diversa: familias criollas, descendientes de inmigrantes, una fuerte presencia paraguaya (el guaraní se escucha en la calle) y comunidades qom, wichí y pilagá, muchas de ellas en barrios como Namqom. Su vínculo con los pueblos originarios también se ve en espacios como la Casa de la Artesanía. Antes de 1879 este territorio ya estaba habitado: la historia de Formosa no empieza con su fundación.', 'Por RN 11 (desde el norte o el sur), RN 81 (desde el oeste), vuelos al Aeropuerto Internacional El Pucú o cruce fluvial desde Alberdi (Paraguay). La Costanera está en el centro, sobre el río.', 'Formosa Hermosa (Ministerio de Turismo de Formosa). Ciudad de Formosa.|https://www.formosahermosa.gob.ar/circuito-formosa-y-herradura/ciudad-de-formosa/
