INSERT INTO preguntas (lugar_id, pregunta, opcion_a, opcion_b, opcion_c, opcion_d, correcta, explicacion) VALUES
(1, '¿Quién fundó la ciudad de Formosa en 1879?', 'Lucio V. Mansilla', 'Luis Jorge Fontana', 'Julio A. Roca', 'Pedro Iturralde', 'b', 'El mayor Luis Jorge Fontana la fundó el 8 de abril de 1879, por sugerencia de Mansilla.'),
(1, '¿De dónde viene el nombre «Formosa»?', 'De un cacique qom', 'De «Punta Hermosa», como la llamaban los españoles', 'De un barco', 'De una flor', 'b', 'Los españoles la llamaban «Punta Hermosa» o «Formosa» por la belleza del río.'),
(1, '¿Cuánto mide aproximadamente la Costanera Vuelta Fermoza?', '700 metros', '7 kilómetros', '70 kilómetros', '1 kilómetro', 'b', 'Tiene unos 7 km frente al río Paraguay.'),
(2, '¿Qué programa de la UNESCO reconoce las Reservas de Biosfera?', 'Patrimonio Mundial', 'MaB: El Hombre y la Biosfera', 'Ciudades Creativas', 'Memoria del Mundo', 'b', 'Laguna Oca integra la red del Programa MaB desde 2001.'),
(2, '¿Qué mono vive en la reserva?', 'Mirikiná', 'Tití', 'Capuchino', 'Gorila', 'a', 'El mono mirikiná es uno de sus mamíferos característicos.'),
(2, '¿Cuántas personas viven aproximadamente en la reserva?', 'Nadie', 'Unas 100', 'Unas 10.000', 'Un millón', 'c', 'Unas 10.000 personas de distintos orígenes viven en la reserva.'),
(3, '¿Cómo se autodenomina el pueblo que vive en Namqom?', 'Toba', 'Qom', 'Mataco', 'Chulupí', 'b', 'Se llaman a sí mismos qom; «toba» es un nombre externo.'),
(3, '¿Qué organizaron las familias para obtener el terreno del barrio?', 'Un partido político', 'Una Comisión por la Tierra', 'Una cooperativa de pesca', 'Un club de fútbol', 'b', 'Según los testimonios, reclamaron organizadas en una Comisión por la Tierra.'),
(3, '¿Qué prejuicio desarma Namqom?', 'Que en Formosa hace calor', 'Que los pueblos originarios solo viven en el monte o en el pasado', 'Que la capital está sobre un río', 'Que hay escuelas', 'b', 'Es una comunidad indígena urbana y actual.'),
(4, '¿Qué pueblos participan en la Casa de la Artesanía?', 'Qom (toba), pilagá y wichí', 'Mapuche y tehuelche', 'Guaraní y kolla', 'Diaguita y huarpe', 'a', 'Allí se exhiben trabajos qom, pilagá y wichí.'),
(4, '¿Qué madera aromática se usa en las tallas?', 'Pino', 'Palo santo', 'Roble', 'Eucalipto', 'b', 'Las tallas en palo santo son muy características.'),
(4, '¿Qué se puede hacer además de comprar?', 'Conversar con los artesanos sobre cómo hacen cada pieza', 'Nada más', 'Pescar', 'Acampar', 'a', 'Se puede conocer el proceso y el significado de cada pieza.'),
(5, '¿En qué año se creó el Parque Nacional Río Pilcomayo?', '1879', '1951', '1992', '2015', 'b', 'Fue creado en 1951 por la Ley Nacional 14.073.'),
(5, '¿Desde cuándo es sitio Ramsar?', 'Desde 1951', 'Desde el 4 de mayo de 1992', 'Desde 2019', 'No es sitio Ramsar', 'b', 'Fue designado humedal de importancia internacional el 4 de mayo de 1992.'),
(5, '¿Qué árbol tiene en el parque su población más austral?', 'Paratodo', 'Pino', 'Sauce', 'Ceibo', 'a', 'El parque protege la población más austral del paratodo.'),
(6, '¿Qué organismo internacional otorgó medidas cautelares a La Primavera?', 'FIFA', 'CIDH', 'UNESCO', 'OMS', 'b', 'La Comisión Interamericana de Derechos Humanos otorgó las medidas MC-404-10.'),
(6, '¿Cuál es el origen del conflicto?', 'Un partido de fútbol', 'El reclamo por sus tierras ancestrales', 'Una elección', 'Un concurso de pesca', 'b', 'El conflicto es por la propiedad ancestral de la tierra.'),
(6, '¿Qué ley provincial de 1984 reconoce derechos a las comunidades aborígenes?', 'Ley 426', 'Ley 1471', 'Ley 14.073', 'Ley 1420', 'a', 'La Ley 426 es la Ley Integral del Aborigen de Formosa.'),
(7, '¿Cómo se llamaba antes Laguna Blanca?', 'Colonia Alfonso', 'Puerto Pilcomayo', 'Fortín Yunká', 'Villa Escolar', 'a', 'Se llamaba Colonia Alfonso, por uno de sus primeros pobladores.'),
(7, '¿Cómo nació la Fiesta del Pomelo en 1972?', 'Como un festival de rock', 'Como actividad escolar para elegir el pomelo más grande', 'Como una feria ganadera', 'Como una regata', 'b', 'Empezó en la cooperadora escolar.'),
(7, '¿Quiénes habitaron primero la zona, según el sitio oficial?', 'Comunidades tobas (qom)', 'Inmigrantes europeos', 'Españoles', 'Nadie', 'a', 'Primero estuvieron las comunidades qom, luego criollos e inmigrantes.'),
(8, '¿Cómo se llamaba la misión franciscana que dio origen a Tacaaglé?', 'San Francisco Solano', 'San Martín de Porres', 'Santa Fe', 'Nuestra Señora de Itatí', 'a', 'Era la misión San Francisco Solano.'),
(8, '¿Junto a qué curso de agua quedó la misión?', 'Riacho Porteño', 'Río Uruguay', 'Río Teuco', 'Laguna Oca', 'a', 'Se trasladó a la ribera del Riacho Porteño.'),
(8, '¿Qué buscaban las misiones con los pueblos indígenas?', 'Respetar su autonomía', 'Asentarlos, evangelizarlos y convertirlos en trabajadores', 'Llevarlos a la ciudad de Buenos Aires', 'Enseñarles inglés', 'b', 'Las misiones eran «reducciones» con fines religiosos y productivos.'),
(9, '¿Qué es un riacho?', 'Una montaña', 'Un curso de agua pequeño', 'Un tipo de pez', 'Una danza', 'b', 'Un riacho es un curso de agua menor que un río.'),
(9, '¿Hacia qué río desaguan muchos riachos formoseños?', 'Río Paraguay', 'Río Colorado', 'Río Negro', 'Río Salado', 'a', 'Vuelcan sus aguas al río Paraguay.'),
(9, '¿Qué misión se asentó a orillas del Riacho El Porteño?', 'Tacaaglé', 'Laishí', 'Nueva Pompeya', 'San Ignacio Miní', 'a', 'La misión de Tacaaglé se trasladó al Riacho Porteño.'),
(10, '¿De qué departamento es cabecera El Espinillo?', 'Pilagás', 'Pirané', 'Laishí', 'Bermejo', 'a', 'Es la cabecera de Pilagás.'),
(10, 'El espinillo es…', 'Un pez', 'Un árbol nativo de flores amarillas', 'Un ave', 'Una montaña', 'b', 'Es un árbol nativo perfumado.'),
(10, '¿A qué pueblo originario recuerda el nombre «Pilagás»?', 'Pilagá', 'Mapuche', 'Guaraní', 'Diaguita', 'a', 'El nombre del departamento recuerda al pueblo pilagá.'),
(11, '¿En qué año fue declarada Monumento Histórico Nacional la ex misión de Laishí?', '1901', '1955', '1989', '2019', 'c', 'Fue declarada por el Decreto 325/1989.'),
(11, '¿Con cuántas familias tobas comenzó la misión?', '6', '26', '156', '1.000', 'b', 'Empezó con 26 familias y llegó a 156 en diez años.'),
(11, '¿Qué pregunta plantea la historia crítica sobre la misión?', 'Cuánto costó la iglesia', 'Qué lugar ocupa la visión indígena en el relato', 'Quién ganó la fiesta', 'Cuántos turistas llegan', 'b', 'Se busca recuperar la mirada indígena, no solo la de los misioneros.'),
(12, '¿Qué fiesta nacional se celebra en Herradura?', 'De la Corvina de Río', 'Del Pomelo', 'Del Río', 'De la Vendimia', 'a', 'Herradura es sede de la Fiesta Nacional de la Corvina de Río.'),
(12, '¿En la confluencia de qué cursos de agua está Herradura?', 'Riacho Salado y río Paraguay', 'Río Bermejo y río Teuco', 'Río Pilcomayo y río Paraná', 'Riacho Porteño y Laguna Blanca', 'a', 'Está donde el riacho Salado se une al río Paraguay.'),
(12, '¿A qué misiones se remontan sus orígenes?', 'Jesuíticas del Santo Rosario y San Carlos del Timbó', 'Franciscanas de Tacaaglé', 'Salesianas de la Patagonia', 'Ninguna', 'a', 'Sus orígenes se remontan a esas misiones jesuíticas.'),
(13, '¿Qué pueblo vive en las comunidades de Laishí?', 'Qom', 'Kolla', 'Ranquel', 'Selk''nam', 'a', 'Son comunidades qom.'),
(13, '¿A qué familia lingüística pertenece el qom?', 'Guaycurú', 'Quechua', 'Tupí', 'Arawak', 'a', 'El qom y el pilagá son lenguas guaycurúes.'),
(13, '¿Por qué son importantes las memorias familiares de la comunidad?', 'Porque permiten contar la historia de la misión desde la mirada indígena', 'Porque reemplazan al Museo', 'No son importantes', 'Porque son secretas', 'a', 'Ayudan a recuperar las historias que faltan.'),
(14, '¿De qué idioma proviene el nombre Pirané?', 'Quechua', 'Guaraní', 'Mapuche', 'Latín', 'b', 'Su origen es guaraní.'),
(14, 'En guaraní, «pirá» significa…', 'Pez', 'Sol', 'Árbol', 'Río', 'a', '«Pirá» significa pez.'),
(14, '¿Qué ruta nacional atraviesa Pirané?', 'Ruta 40', 'Ruta 81', 'Ruta 3', 'Ruta 7', 'b', 'La Ruta 81 cruza la provincia de este a oeste.'),
(15, '¿Qué es el palo santo?', 'Un pez', 'Un árbol aromático', 'Un ave', 'Un mineral', 'b', 'Es un árbol nativo de madera perfumada.'),
(15, '¿De qué color es la madera del palo santo?', 'Blanca', 'Verde', 'Azul', 'Negra', 'b', 'Tiene una madera verdosa característica.'),
(15, '¿Por qué hay que cuidar al palo santo?', 'Porque es invasor', 'Porque su explotación excesiva lo amenaza', 'Porque es venenoso', 'No hace falta', 'b', 'La sobreexplotación pone en riesgo a la especie.'),
(16, '¿Cómo se conoce a El Colorado?', 'La Perla del Sur', 'La Capital del Pomelo', 'La Puerta del Oeste', 'La Ciudad del Río', 'a', 'Se la conoce como «la Perla del Sur».'),
(16, '¿Qué representan los tres pilares del Puente Libertad?', 'Tres ríos', 'Los pueblos indígena, inmigrante europeo y criollo', 'Tres gobernadores', 'Tres provincias', 'b', 'Simbolizan los tres grupos que formaron la comunidad.'),
(16, '¿Qué río pasa por El Colorado y lo separa del Chaco?', 'Río Bermejo', 'Río Pilcomayo', 'Río Paraguay', 'Río Uruguay', 'a', 'El Bermejo es el límite natural con el Chaco.'),
(17, '¿Qué río forma el Bañado La Estrella con sus desbordes?', 'Río Paraguay', 'Río Pilcomayo', 'Río Bermejo', 'Río Paraná', 'b', 'Se origina por los desbordes del Pilcomayo.'),
(17, '¿Cuál es el ave emblema del Bañado?', 'Flamenco', 'Jabirú', 'Hornero', 'Cóndor', 'b', 'El jabirú es la cigüeña más grande de América.'),
(17, '¿Qué conflicto estudió Hugo Beck en el Bañado?', 'Entre clubes de fútbol', 'Entre el gobierno provincial y los pobladores aborígenes y criollos', 'Entre turistas', 'Entre Brasil y Bolivia', 'b', 'Beck analiza la política oficial frente a los derechos de los pobladores.'),
(18, '¿Qué pueblo sufrió la masacre de Rincón Bomba?', 'Pilagá', 'Mapuche', 'Guaraní', 'Huarpe', 'a', 'Las víctimas pertenecían al pueblo pilagá.'),
(18, '¿En qué año ocurrió?', '1879', '1947', '1982', '2010', 'b', 'Comenzó el 10 de octubre de 1947.'),
(18, '¿Cómo la calificó la Justicia Federal en 2019?', 'Accidente', 'Crimen de lesa humanidad', 'Hecho aislado', 'Conflicto vecinal', 'b', 'Fue reconocida como crimen de lesa humanidad.'),
(19, '¿Qué ruta nacional pasa por Las Lomitas?', 'Ruta 81', 'Ruta 22', 'Ruta 9', 'Ruta 3', 'a', 'Las Lomitas está sobre la Ruta 81.'),
(19, '¿A qué humedal se accede desde Las Lomitas?', 'Iberá', 'Bañado La Estrella', 'Esteros del Ñeembucú', 'Laguna Mar Chiquita', 'b', 'Es la puerta al Bañado La Estrella.'),
(19, '¿Qué hecho histórico ocurrió cerca de Las Lomitas?', 'La fundación de Formosa', 'La masacre de Rincón Bomba', 'La Batalla de Caseros', 'El Cruce de los Andes', 'b', 'Rincón Bomba está cerca de Las Lomitas.'),
(20, '¿Con qué obra se fundó Laguna Yema en 1925?', 'El ferrocarril', 'Un puerto', 'Un aeropuerto', 'Una represa hidroeléctrica', 'a', 'Nació junto con la construcción del ferrocarril.'),
(20, '¿A quién recuerda el nombre del pueblo, según el sitio oficial?', 'A un cacique wichí', 'A un militar', 'A un santo', 'A un río', 'a', 'Recibe su nombre de un cacique wichí.'),
(20, '¿Qué superficie tiene el embalse construido en los años 80?', '14.500 ha', '100 ha', '1 millón de ha', '50 ha', 'a', 'El embalse cubre 14.500 hectáreas.'),
(21, '¿Cuál es la especie emblema de la Reserva Natural Formosa?', 'Tatú carreta', 'Jabirú', 'Yaguareté', 'Carpincho', 'a', 'El tatú carreta es el armadillo vivo más grande del mundo.'),
(21, '¿Entre qué ríos está la reserva?', 'Teuco y Teuquito', 'Paraguay y Paraná', 'Pilcomayo y Bermejo', 'Salado y Porteño', 'a', 'Se ubica entre el Teuco (Bermejo) y el Teuquito.'),
(21, '¿Qué pueblo originario vive en las comunidades de la región?', 'Wichí', 'Mapuche', 'Guaraní', 'Diaguita', 'a', 'Varias comunidades wichí viven en la zona.'),
(22, '¿Qué fibra usan las mujeres wichí para tejer?', 'Chaguar', 'Seda', 'Nylon', 'Lana de oveja', 'a', 'El chaguar es la fibra tradicional.'),
(22, '¿Cómo se llama el bolso tejido wichí?', 'Yica', 'Poncho', 'Aguayo', 'Mochila', 'a', 'La yica es el bolso tradicional.'),
(22, 'Según el Censo 2022, ¿dónde vive la mayoría de la población wichí?', 'Salta y Formosa', 'Buenos Aires', 'Mendoza', 'Tierra del Fuego', 'a', 'Cerca del 78% vive entre Salta y Formosa.'),
(23, '¿A qué pueblo hace referencia el nombre «Matacos»?', 'Wichí', 'Qom', 'Pilagá', 'Guaraní', 'a', '«Mataco» era el nombre externo dado a los wichí.'),
(23, '¿Por qué es importante analizar ese nombre?', 'Porque es un nombre impuesto desde afuera', 'Porque es muy largo', 'Porque es en inglés', 'No es importante', 'a', 'Muestra cómo se nombró al otro desde una mirada ajena.'),
(23, '¿Junto a qué medio de transporte nació la ciudad?', 'El ferrocarril', 'El avión', 'El barco', 'El subte', 'a', 'Creció junto a las vías del tren.'),
(24, '¿Qué es el chaguar?', 'Una planta del monte', 'Un animal', 'Un río', 'Un instrumento', 'a', 'Es una planta de cuyas hojas se obtiene fibra.'),
(24, '¿Cómo se hila tradicionalmente la fibra?', 'Sobre la pierna', 'Con máquinas industriales', 'Con impresoras 3D', 'No se hila', 'a', 'Las artesanas la hilan frotándola sobre la pierna.'),
(24, 'Los diseños geométricos wichí representan…', 'Elementos de la naturaleza', 'Marcas comerciales', 'Letras latinas', 'Números romanos', 'a', 'Representan animales y elementos del monte.'),
(25, '¿Cuál es el segundo bosque más grande de Sudamérica?', 'Gran Chaco', 'Yungas', 'Bosque Andino', 'Mata Atlántica', 'a', 'El Gran Chaco sigue a la Amazonía.'),
(25, '¿De dónde viene el nombre «quebracho»?', 'De «quiebra hacha»', 'De un cacique', 'Del guaraní «agua»', 'De un explorador', 'a', 'Por la dureza de su madera.'),
(25, '¿Qué animal habita el monte chaqueño?', 'Oso hormiguero', 'Pingüino', 'Llama', 'Ballena', 'a', 'El oso hormiguero vive en el Chaco.'),
(26, '¿Quién fue Enrique Mosconi?', 'El primer director de YPF', 'Un futbolista', 'Un pintor', 'Un cacique', 'a', 'Dirigió YPF en sus comienzos.'),
(26, '¿Cuál es el departamento más occidental de Formosa?', 'Ramón Lista', 'Formosa', 'Laishí', 'Pilcomayo', 'a', 'Ramón Lista está en el extremo oeste.'),
(26, '¿Qué muestran muchos nombres de lugares del oeste?', 'Cómo el Estado nombró el territorio al incorporarlo', 'Nombres de comidas', 'Nombres de canciones', 'Nada', 'a', 'Recuerdan a militares, exploradores y funcionarios.'),
(27, '¿Qué lengua se habla cotidianamente en El Potrillo?', 'Wichí', 'Inglés', 'Portugués', 'Quechua', 'a', 'La lengua wichí está muy viva allí.'),
(27, '¿Qué alimento silvestre es muy valorado?', 'Miel del monte', 'Caviar', 'Salmón', 'Trufa', 'a', 'La miel silvestre es muy importante.'),
(27, '¿Por qué es importante la escuela intercultural bilingüe?', 'Para que la lengua wichí no se pierda', 'Para dejar de hablar wichí', 'No es importante', 'Para aprender solo inglés', 'a', 'Ayuda a mantener viva la lengua.'),
(28, '¿Con qué dos países limita Formosa cerca del extremo noroeste?', 'Bolivia y Paraguay', 'Chile y Perú', 'Brasil y Uruguay', 'Paraguay y Brasil', 'a', 'Allí convergen Argentina, Bolivia y Paraguay.'),
(28, '¿Qué pez migra por el Pilcomayo y es clave para las comunidades?', 'Sábalo', 'Salmón', 'Atún', 'Trucha', 'a', 'El sábalo es fundamental en la alimentación.'),
(28, '¿Qué humedal forman los desbordes del Pilcomayo?', 'Bañado La Estrella', 'Iberá', 'Laguna Oca', 'Mar Chiquita', 'a', 'El Bañado La Estrella nace de sus desbordes.');
INSERT INTO pueblos (nombre, nombre_impuesto, descripcion, color, icono, orden) VALUES
('Qom', '«Tobas»', 'Pueblo de la familia guaycurú. Viven en el este y centro de la provincia, en comunidades como Namqom, La Primavera, Laishí y Misión Tacaaglé. Mantienen su lengua, su música y su cestería, y son protagonistas de reclamos por la tierra.', '#C2552F', 'fa-people-group', 1),
('Wichí', '«Matacos»', 'Pueblo de la familia mataco-mataguaya que vive en el oeste formoseño. Grandes conocedores del monte, la pesca y la miel silvestre; sus tejidos en chaguar son reconocidos en todo el mundo. Cerca del 78% de la población wichí del país vive entre Salta y Formosa (Censo 2022).', '#E9A23B', 'fa-feather', 2),
('Pilagá', 'Sin otro nombre impuesto', 'Pueblo guaycurú del centro-oeste, emparentado con los qom. Su historia incluye la masacre de Rincón Bomba (1947), reconocida en 2019 como crimen de lesa humanidad. Viven en la zona del Bañado La Estrella y Las Lomitas.', '#2E9E6A', 'fa-leaf', 3),
('Nivaclé', '«Chulupí»', 'Pueblo de la familia mataco-mataguaya, con presencia en el oeste de Formosa, en Salta y en el Chaco paraguayo. Pescadores del Pilcomayo con una rica tradición oral.', '#2A9DAD', 'fa-water', 4);
